```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

@base <http://example.org/onto/assessment#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" ;
  rdfs:comment "Ontology modeling classification of educational assessment, test items, reliability and validity, built strictly from a corpus on educational assessment. Several passages present conflicting classification claims (e.g. coordinate lists vs. subordination); both are encoded with explanatory comments as required." .

################################################################
# TOP CLASSES
################################################################

ea:EducationalAssessment a owl:Class ;
  rdfs:label "Educational Assessment" ;
  skos:altLabel "assessment", "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in other topics. 'An examination (exam) is a test.'" .

ea:TestItem a owl:Class ;
  rdfs:label "Test Item" ;
  skos:altLabel "question", "item" ;
  rdfs:comment "Component of a test consisting of a prompt and, in closed formats, response options. 'Item' is preferred since many items are not phrased as questions." .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem ;
  rdfs:label "has item" .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test ;
  rdfs:label "is item of" .

################################################################
# AXIS 1: GRANULARITY
################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:GranularityCategory ;
  rdfs:label "has granularity" ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole." .

ea:GranularityCategory a owl:Class .
ea:LearnerLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:ProgramLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemLevel a owl:Class ; rdfs:subClassOf ea:GranularityCategory .

ea:GranularityCategory owl:disjointUnionOf
  ( ea:LearnerLevel ea:LearningCommunityLevel ea:CourseLevel
    ea:ProgramLevel ea:InstitutionLevel ea:EducationalSystemLevel ) .

################################################################
# AXIS 2: PURPOSE (Placement / Formative / Summative / Diagnostic)
################################################################

ea:hasPurpose a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:PurposeCategory ;
  rdfs:label "has purpose" ;
  rdfs:comment "Not declared functional: the corpus states diagnostic assessment is simultaneously a coordinate 4th purpose AND a form of formative assessment, requiring an individual assessment to be able to instantiate more than one purpose value without contradiction." .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a 4th coordinate category alongside placement, formative and summative (modeled via the disjoint PurposeCategory partition above); another passage states 'A common form of formative assessment is diagnostic assessment', modeled here as rdfs:subClassOf FormativeAssessment. Both claims are retained as required." .

################################################################
# AXIS 3: ANSWER CORRECTNESS (Objective / Subjective)
################################################################

ea:hasAnswerCorrectness a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AnswerCorrectnessCategory ;
  rdfs:label "has answer correctness" .

ea:AnswerCorrectnessCategory a owl:Class .
ea:SingleCorrectAnswerType a owl:Class ; rdfs:subClassOf ea:AnswerCorrectnessCategory .
ea:MultipleCorrectAnswerType a owl:Class ; rdfs:subClassOf ea:AnswerCorrectnessCategory .

ea:AnswerCorrectnessCategory owl:disjointUnionOf
  ( ea:SingleCorrectAnswerType ea:MultipleCorrectAnswerType ) .

ea:ObjectiveAssessment a owl:Class ;
  rdfs:label "Objective Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerCorrectness ; owl:someValuesFrom ea:SingleCorrectAnswerType ] ) ] ;
  rdfs:comment "Objective assessment is a form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  rdfs:label "Subjective Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerCorrectness ; owl:someValuesFrom ea:MultipleCorrectAnswerType ] ) ] ;
  rdfs:comment "Subjective assessment is a form of questioning that may have more than one correct answer." .

################################################################
# AXIS 4: REFERENCING (Criterion / Norm / Ipsative)
################################################################

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ReferenceCategory ;
  rdfs:label "has reference type" .

ea:ReferenceCategory a owl:Class .
ea:CriterionReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:NormReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:IpsativeReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .

ea:ReferenceCategory owl:disjointUnionOf
  ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) .

ea:CriterionReferencedAssessment a owl:Class ;
  rdfs:label "Criterion-Referenced Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  rdfs:label "Norm-Referenced Assessment" ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  rdfs:label "Ipsative Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:CriterionReferencedTest a owl:Class ;
  rdfs:label "Criterion-Referenced Test" ;
  skos:altLabel "CRT", "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] .

ea:NormReferencedTest a owl:Class ;
  rdfs:label "Norm-Referenced Test" ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal ;
  rdfs:label "has cut score" .

################################################################
# AXIS 5: FORMALITY (Formal / Informal)
################################################################

ea:hasFormalityType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:FormalityCategory ;
  rdfs:label "has formality type" .

ea:FormalityCategory a owl:Class .
ea:FormalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:FormalityCategory owl:disjointUnionOf ( ea:FormalType ea:InformalType ) .

ea:FormalAssessment a owl:Class ;
  rdfs:label "Formal Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:FormalType ] ) ] .

ea:InformalAssessment a owl:Class ;
  rdfs:label "Informal Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:InformalType ] ) ] .

################################################################
# AXIS 6: ADMINISTRATION SCOPE (Internal / External)
################################################################

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AdministrationScopeCategory ;
  rdfs:label "has administration scope" .

ea:AdministrationScopeCategory a owl:Class .
ea:InternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:ExternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .

ea:AdministrationScopeCategory owl:disjointUnionOf ( ea:InternalScope ea:ExternalScope ) .

ea:InternalAssessment a owl:Class ;
  rdfs:label "Internal Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalScope ] ) ] ;
  rdfs:comment "Set and marked by the school." .

ea:ExternalAssessment a owl:Class ;
  rdfs:label "External Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalScope ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

################################################################
# AXIS 7: STANDARDIZATION (Standardized / Non-standardized) - on Test
################################################################

ea:hasStandardizationType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory ;
  rdfs:label "has standardization type" .

ea:StandardizationCategory a owl:Class .
ea:StandardizedType a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedType a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedType ea:NonStandardizedType ) .

ea:StandardizedTest a owl:Class ;
  rdfs:label "Standardized Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationType ; owl:someValuesFrom ea:StandardizedType ] ) ] ;
  rdfs:comment "A test that is administered and scored in a consistent or standard manner." .

ea:NonStandardizedTest a owl:Class ;
  rdfs:label "Non-Standardized Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationType ; owl:someValuesFrom ea:NonStandardizedType ] ) ] .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures knowledge/skills learned in school; 'backward-looking'." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Attempts to predict ability to succeed; 'forward-looking'." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest ) .

################################################################
# AXIS 8: STAKES (High / Low)
################################################################

ea:hasStakesType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:StakesCategory ;
  rdfs:label "has stakes type" .

ea:StakesCategory a owl:Class .
ea:HighStakesType a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesType a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesType ea:LowStakesType ) .

ea:HighStakesTest a owl:Class ;
  rdfs:label "High-Stakes Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesType ; owl:someValuesFrom ea:HighStakesType ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance, or used to make important decisions about students, educators, schools, or districts." .

ea:LowStakesTest a owl:Class ;
  rdfs:label "Low-Stakes Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesType ; owl:someValuesFrom ea:LowStakesType ] ) ] .

ea:CompetitiveExamination a owl:Class ;
  rdfs:label "Competitive Examination" ;
  rdfs:subClassOf ea:NormReferencedTest, ea:HighStakesTest ;
  rdfs:comment "Competitive exams are norm-referenced, high-stakes tests in which candidates are ranked and top rankers are selected." .

################################################################
# NOTE ON CROSS-CUTTING NATURE OF AXES
################################################################

ea:EducationalAssessment rdfs:comment
  "Most tests can be classified on multiple categories simultaneously (e.g. standardized AND high-stakes AND multiple-choice); the axes above (purpose, answer-correctness, reference type, formality, administration scope, standardization, stakes) are therefore modeled as independent, cross-cutting, non-mutually-exclusive dimensions, consistent with the corpus statement that 'a test can be both standardized and also a high-stakes test'." .

################################################################
# OBJECTIVE / SUBJECTIVE ITEM TYPES
################################################################

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ObjectiveItem owl:disjointWith ea:SubjectiveItem .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:OneBestAnswerItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Second family of multiple-choice question: requires choosing only one answer from a list." .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists true/false as a sibling objective-question type alongside multiple-choice, multiple-response and matching (modeled above as pairwise disjoint siblings). Another passage states 'There are two families of multiple-choice questions. The first family is known as the True/False question', modeled here as rdfs:subClassOf MultipleChoiceItem. Both claims are retained, producing a deliberately inconsistent but corpus-faithful model." .

ea:hasStemText a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range xsd:string ;
  rdfs:label "has stem text" .

ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Key owl:disjointWith ea:Distractor .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:label "has option" .

ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:Key ;
  rdfs:label "has key" .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:Distractor ;
  rdfs:label "has distractor" .

ea:MultipleChoiceItem owl:equivalentClass [
    owl:intersectionOf ( ea:ObjectiveItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:cardinality "1"^^xsd:nonNegativeInteger ]
    )
  ] ;
  rdfs:comment "Only one answer may be keyed as correct (exactly one Key)." .

ea:MultipleResponseItem owl:equivalentClass [
    owl:intersectionOf ( ea:ObjectiveItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minCardinality "2"^^xsd:nonNegativeInteger ]
    )
  ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .

################################################################
# RUBRIC
################################################################

ea:Rubric a owl:Class ;
  rdfs:label "Rubric" ;
  skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "Developmental rubrics are a subset of analytical rubrics." .

ea:HolisticRubric owl:disjointWith ea:AnalyticRubric .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Rubric ;
  rdfs:label "has rubric" .

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
ea:HolisticGrading owl:disjointWith ea:AnalyticGrading .

################################################################
# VALIDITY
################################################################

ea:Validity a owl:Class ;
  rdfs:label "Validity" ;
  skos:altLabel "test validity" ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity", "subject-matter validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  skos:altLabel "divergent validity" .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment
  "TENSION: a passage presents content validity, criterion validity, construct validity, face validity, and consequential validity as a coordinate, mutually exclusive list of validity-evidence categories (modeled above via owl:AllDisjointClasses). Another passage states construct validity 'subsumes all other types of validity' / is 'the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity', modeled via explicit rdfs:subClassOf axioms. Both claims are retained even though jointly they force the subsumed classes to be empty." .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Validity ;
  rdfs:label "has validity" .

ea:hasValidityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Validity ;
  rdfs:range xsd:decimal ;
  rdfs:label "has validity coefficient" .

################################################################
# RELIABILITY
################################################################

ea:Reliability a owl:Class ;
  rdfs:label "Reliability" ;
  skos:altLabel "test reliability" ;
  rdfs:comment "The freedom of a measure from measurement error; consistency of an assessment." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "inter-rater agreement" .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .

ea:Reliability owl:disjointUnionOf
  ( ea:InterRaterReliability ea:TestRetestReliability
    ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability ;
  rdfs:comment "Test-retest reliability 'includes intra-rater reliability'." .

ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  skos:altLabel "alternate-forms reliability" ;
  rdfs:comment "When dealing with forms, inter-method reliability may be termed parallel-forms reliability." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Split-half reliability treats the two halves of a measure as alternate forms, yet is used, via the Spearman-Brown formula, to estimate internal-consistency reliability; both affinities are noted." .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Reliability ;
  rdfs:label "has reliability" .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal ;
  rdfs:label "has reliability coefficient" ;
  rdfs:comment "Ranges between 0.00 (much error) and 1.00 (no error)." .

# A second, distinct four-part partition of "types of reliability" named by source of error.
ea:ReliabilityFactor a owl:Class ;
  rdfs:comment "TENSION: the corpus separately states 'There are four types of reliability: student-related, rater-related, test administration-related, and test-related', naming a different four-part partition than the 'general classes of reliability estimates' (InterRater, TestRetest, InterMethod, InternalConsistency) modeled above on ea:Reliability. Both are retained as distinct classes/partitions." .

ea:StudentRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:RaterRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:TestAdministrationRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .
ea:TestRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityFactor .

ea:ReliabilityFactor owl:disjointUnionOf
